import{_ as e,o as r,c as t,a0 as i}from"./chunks/framework.akKRIpjQ.js";const _=JSON.parse('{"title":"10 · 常见问题（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/10-faq.md","filePath":"zh/guide/10-faq.md"}'),o={name:"zh/guide/10-faq.md"};function l(h,a,n,d,s,c){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="_10-·-常见问题-faq" tabindex="-1">10 · 常见问题（FAQ） <a class="header-anchor" href="#_10-·-常见问题-faq" aria-label="Permalink to &quot;10 · 常见问题（FAQ）&quot;">​</a></h1><h3 id="_1-app-是不是完全免费的" tabindex="-1">1. App 是不是完全免费的? <a class="header-anchor" href="#_1-app-是不是完全免费的" aria-label="Permalink to &quot;1. App 是不是完全免费的?&quot;">​</a></h3><p><strong>是</strong>。无广告、无内购、无会员。</p><h3 id="_2-升级到-v1-1-会收费吗" tabindex="-1">2. 升级到 V1.1 会收费吗? <a class="header-anchor" href="#_2-升级到-v1-1-会收费吗" aria-label="Permalink to &quot;2. 升级到 V1.1 会收费吗?&quot;">​</a></h3><p><strong>不会</strong>。</p><h3 id="_3-数据会被上传吗" tabindex="-1">3. 数据会被上传吗? <a class="header-anchor" href="#_3-数据会被上传吗" aria-label="Permalink to &quot;3. 数据会被上传吗?&quot;">​</a></h3><p><strong>不上传</strong>，除非你点 <a href="./09-feedback.html">反馈</a>。</p><h3 id="_4-我卸载了-数据恢复不了" tabindex="-1">4. 我卸载了，数据恢复不了？ <a class="header-anchor" href="#_4-我卸载了-数据恢复不了" aria-label="Permalink to &quot;4. 我卸载了，数据恢复不了？&quot;">​</a></h3><p>如果你没配云同步——是的，没云备份。建议定期用 JSON 导出做手动备份（<a href="./07-settings.html#数据管理">07 · 设置 → 数据管理</a>）。如果你已配云同步（<a href="./06-cloud-sync.html">06 · 云同步</a>），新设备登录同一账号就能拉回来。</p><h3 id="_5-ios-什么时候有" tabindex="-1">5. iOS 什么时候有? <a class="header-anchor" href="#_5-ios-什么时候有" aria-label="Permalink to &quot;5. iOS 什么时候有?&quot;">​</a></h3><p>暂无可用版本。详见 <a href="./00-introduction.html#支持平台">00 · 支持平台</a>。</p><h3 id="_6-启动后空白-卡死怎么办" tabindex="-1">6. 启动后空白 / 卡死怎么办? <a class="header-anchor" href="#_6-启动后空白-卡死怎么办" aria-label="Permalink to &quot;6. 启动后空白 / 卡死怎么办?&quot;">​</a></h3><ol><li>重启 App</li><li>若仍异常：<code>我的 → 数据管理 → 删除全部数据</code>（先把 JSON 导出）</li><li>还不行：卸载重装</li></ol><h3 id="_7-怎么把-app-图标放到桌面" tabindex="-1">7. 怎么把 App 图标放到桌面? <a class="header-anchor" href="#_7-怎么把-app-图标放到桌面" aria-label="Permalink to &quot;7. 怎么把 App 图标放到桌面?&quot;">​</a></h3><p>Android 安装后桌面会有图标。长按拖到文件夹里也行。</p><h3 id="_8-我用了第三方启动器-如-nova-图标不一样" tabindex="-1">8. 我用了第三方启动器（如 Nova），图标不一样？ <a class="header-anchor" href="#_8-我用了第三方启动器-如-nova-图标不一样" aria-label="Permalink to &quot;8. 我用了第三方启动器（如 Nova），图标不一样？&quot;">​</a></h3><p>Android 自适应图标在你启动器里可能渲染为不同形状，但功能不影响。</p><h3 id="_9-可以导出为-pdf-excel-吗" tabindex="-1">9. 可以导出为 PDF / Excel 吗? <a class="header-anchor" href="#_9-可以导出为-pdf-excel-吗" aria-label="Permalink to &quot;9. 可以导出为 PDF / Excel 吗?&quot;">​</a></h3><p>V1.0 仅 JSON 导出。V1.1 起会加 CSV（适合 Excel）。</p><h3 id="_10-我能贡献翻译吗" tabindex="-1">10. 我能贡献翻译吗? <a class="header-anchor" href="#_10-我能贡献翻译吗" aria-label="Permalink to &quot;10. 我能贡献翻译吗?&quot;">​</a></h3><p>暂未开放翻译协作。V1.0 起官方语言：简体中文 / English。</p><h3 id="_11-这个项目会开源吗" tabindex="-1">11. 这个项目会开源吗? <a class="header-anchor" href="#_11-这个项目会开源吗" aria-label="Permalink to &quot;11. 这个项目会开源吗?&quot;">​</a></h3><p><a href="./00-introduction.html#当前不-做的事">V1.0 上架后另行评估</a>。当前不提供源代码 / 二进制构建脚本。</p><h3 id="_12-我在测试中遇到-bug-怎么报告" tabindex="-1">12. 我在测试中遇到 Bug，怎么报告? <a class="header-anchor" href="#_12-我在测试中遇到-bug-怎么报告" aria-label="Permalink to &quot;12. 我在测试中遇到 Bug，怎么报告?&quot;">​</a></h3><p><strong>最快</strong>：App 内 <code>我的 → 发送反馈</code>（详见 <a href="./09-feedback.html">09 · 反馈</a>）。 <strong>邮件</strong>：<a href="mailto:acecrushdev@gmail.com" target="_blank" rel="noreferrer">acecrushdev@gmail.com</a>（含日志截图）。</p><h3 id="_13-ios-safari-链接到-app-会失败吗" tabindex="-1">13. iOS Safari 链接到 App 会失败吗? <a class="header-anchor" href="#_13-ios-safari-链接到-app-会失败吗" aria-label="Permalink to &quot;13. iOS Safari 链接到 App 会失败吗?&quot;">​</a></h3><p><strong>会</strong>。当前没有 iOS 版本，Universal Links 也没配置——直接打开官网即可。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./06-cloud-sync.html">06 · 云同步</a></li><li><a href="./07-settings.html">07 · 设置</a></li><li><a href="./08-privacy.html">08 · 隐私</a></li><li><a href="./09-feedback.html">09 · 反馈</a></li></ul>',29)])])}const u=e(o,[["render",l]]);export{_ as __pageData,u as default};
